import{_ as e,o as r,c as t,a6 as o}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"隱私權政策","description":"蒼藍星圖鑑應用程式與網站的隱私權政策，說明本機資料、裝置備份、電子郵件聯絡、資料保留與刪除方式。","frontmatter":{"description":"蒼藍星圖鑑應用程式與網站的隱私權政策，說明本機資料、裝置備份、電子郵件聯絡、資料保留與刪除方式。","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/privacy/"}],["meta",{"property":"og:title","content":"隱私權政策 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"蒼藍星圖鑑應用程式與網站的隱私權政策，說明本機資料、裝置備份、電子郵件聯絡、資料保留與刪除方式。"}]]},"headers":[],"relativePath":"zh-hant/privacy/index.md","filePath":"zh-hant/privacy/index.md"}'),i={name:"zh-hant/privacy/index.md"};function n(l,a,h,p,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="隱私權政策" tabindex="-1">隱私權政策 <a class="header-anchor" href="#隱私權政策" aria-label="Permalink to &quot;隱私權政策&quot;">​</a></h1><p>生效日期：2026 年 10 月 31 日<br> 更新日期：2026 年 11 月 10 日（補充自願贊助的支付資訊說明）</p><p>本政策適用於蒼藍星圖鑑（Sapphire Star Codex）的 iOS、Android 與 HarmonyOS 應用程式，以及本網站。開發者為 <strong>eurekaffeine（刘耀晨）</strong>。如有隱私相關問題，請聯絡 <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>。</p><p>應用程式目前處於開發階段，各平台的功能可能有所不同。以下說明目前應用程式與網站的資料處理方式。使用應用程式無需註冊帳號。</p><h2 id="本機資料" tabindex="-1">本機資料 <a class="header-anchor" href="#本機資料" aria-label="Permalink to &quot;本機資料&quot;">​</a></h2><p>應用程式為保留設定並提供相關功能，會在裝置上儲存資料。依使用的平台與功能，可能包括：</p><ul><li>遊戲、語言、外觀等設定。</li><li>搜尋紀錄，以及用來恢復瀏覽位置的頁面狀態。</li><li>收藏的魔物、裝備及其他圖鑑資料。</li><li>儲存的配裝、自訂配裝名稱、裝飾品數量、護石與防具庫存。</li></ul><p>這些資料用於資料瀏覽、搜尋、收藏與配裝。應用程式不會將其上傳給開發者，開發者亦未營運帳號或雲端同步服務。</p><h2 id="權限與自動收集" tabindex="-1">權限與自動收集 <a class="header-anchor" href="#權限與自動收集" aria-label="Permalink to &quot;權限與自動收集&quot;">​</a></h2><p>目前的應用程式未整合廣告、追蹤、使用分析或自動上傳當機報告的 SDK。現有功能無需存取聯絡人、位置、相機、麥克風或相片圖庫，也不收集廣告識別碼。</p><p>作業系統與應用程式商店可能依各自的設定與政策，獨立處理安裝或診斷資訊。平台提供給開發者的診斷資訊僅用於排查應用程式問題。</p><h2 id="電子郵件聯絡" tabindex="-1">電子郵件聯絡 <a class="header-anchor" href="#電子郵件聯絡" aria-label="Permalink to &quot;電子郵件聯絡&quot;">​</a></h2><p>透過電子郵件聯絡開發者時，開發者會收到您的電子郵件地址、信件內容及主動提供的附件。這些資訊僅用於回覆、排查問題與處理隱私請求，不用於廣告或行銷郵件。請僅提供處理問題所需的資訊。</p><h2 id="網站、備份與其他服務" tabindex="-1">網站、備份與其他服務 <a class="header-anchor" href="#網站、備份與其他服務" aria-label="Permalink to &quot;網站、備份與其他服務&quot;">​</a></h2><p><strong>網站代管。</strong> 本網站由 GitHub Pages 代管，未加入流量分析、廣告 Cookie 或追蹤像素。站內搜尋在瀏覽器中執行，顯示與搜尋偏好也可能儲存在瀏覽器中。造訪網站時，GitHub 會接收 IP 位址、瀏覽器資訊等技術請求資訊，具體處理方式請參閱 <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub 隱私聲明</a>。</p><p><strong>自願贊助。</strong> 如您選擇透過支付寶或微信支付支持開發者，付款由相應平台依其條款與隱私權政策處理。本網站僅展示靜態收款 QR Code，不嵌入支付 SDK，也不會接收支付憑證。開發者可能查看支付平台向收款方提供的交易資訊，例如金額、時間、付款人顯示名稱與付款備註。這些紀錄用於核對贊助款項及處理付款問題，並依支付平台的管理規則與適用的紀錄保留要求保存。</p><p><strong>裝置備份。</strong> 依系統設定，應用程式資料可能包含於裝置或雲端備份中。備份由相應的平台服務商管理，開發者無法代為讀取或刪除。</p><p><strong>郵件與外部連結。</strong> 開發者使用 Gmail 接收郵件，Google 依 <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 隱私權政策</a>處理提供郵件服務所需的資訊。造訪外部網站或應用程式商店時，適用相應服務的隱私權政策。網站代管、郵件與備份服務商可能在您所在國家或地區以外處理資訊。</p><h2 id="資料分享、保留與刪除" tabindex="-1">資料分享、保留與刪除 <a class="header-anchor" href="#資料分享、保留與刪除" aria-label="Permalink to &quot;資料分享、保留與刪除&quot;">​</a></h2><p>開發者不會出售、出租個人資訊，也不會為廣告目的分享個人資訊。聯絡郵件由上述郵件服務商處理。在法律要求或您明確提出相應請求時，開發者可能提供其實際持有的資訊。</p><ul><li><strong>應用程式資料：</strong> 可透過應用程式現有的刪除功能或裝置設定清理。清理本機資料時，請選擇同時刪除應用程式與資料的選項。保留資料的卸載或封存方式不會清除本機資料。備份需另行管理，重新安裝時也可能還原備份資料。</li><li><strong>網站偏好：</strong> 儲存在瀏覽器中，直至您清除本網站的資料或瀏覽器自動清理。</li><li><strong>郵件與主動提供的診斷資訊：</strong> 僅在處理問題、後續追蹤或履行法律義務所需的期間保留。您可請求刪除已提供的資訊，法律要求保留的情況除外。</li><li><strong>服務商持有的資料：</strong> 包括備份與網站存取紀錄，由服務商依其規則保留與管理。</li></ul><p>如需查閱、更正或刪除已向開發者提供的資訊，請透過下方信箱聯絡。僅儲存在裝置上的紀錄，開發者無法遠端讀取或刪除。</p><h2 id="資料安全" tabindex="-1">資料安全 <a class="header-anchor" href="#資料安全" aria-label="Permalink to &quot;資料安全&quot;">​</a></h2><p>本機資料受作業系統提供的應用程式儲存機制保護。本網站使用 HTTPS。開發者僅為處理支援與隱私請求而存取相關郵件，並使用郵件服務商提供的安全措施。</p><h2 id="兒童與未成年人的隱私" tabindex="-1">兒童與未成年人的隱私 <a class="header-anchor" href="#兒童與未成年人的隱私" aria-label="Permalink to &quot;兒童與未成年人的隱私&quot;">​</a></h2><p>使用應用程式無需填寫個人資料或出生日期，開發者不會有意向兒童收集個人資訊。如家長或監護人認為兒童曾向開發者提供個人資訊，請聯絡開發者處理刪除事宜。</p><h2 id="政策更新" tabindex="-1">政策更新 <a class="header-anchor" href="#政策更新" aria-label="Permalink to &quot;政策更新&quot;">​</a></h2><p>資料處理方式變更時，本政策與更新日期將相應調整。重要變更將透過網站或應用程式更新說明告知。新功能如需另行申請權限或取得同意，將於相應操作時提出；本政策本身不構成對相關操作的授權或同意。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to &quot;聯絡我們&quot;">​</a></h2><p>開發者：<strong>eurekaffeine（刘耀晨）</strong><br> 應用程式：<strong>蒼藍星圖鑑 / Sapphire Star Codex</strong><br> 電子郵件：<a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',30)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
